      && verifier.VerifyString(tablePos, 26 /*PRODUCER_ID*/, false)
      && verifier.VerifyString(tablePos, 28 /*PRODUCER_VERSION*/, false)
      && verifier.VerifyString(tablePos, 30 /*GENERATED_AT*/, false)
      && verifier.VerifyString(tablePos, 32 /*EXPIRES_AT*/, false)
      && verifier.VerifyVectorOfStrings(tablePos, 34 /*TAGS*/, false)
      && verifier.VerifyString(tablePos, 36 /*NOTES*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
